import sys

def main():
    input = sys.stdin.readline
    n = int(input())
    a = list(map(int, input().split()))

    odd_count = sum(x % 2 == 1 for x in a)

    if n == 1:
        print("Fennec")
    elif n == 2:
        print("Snuke")
    elif n == 3:
        print("Fennec" if odd_count > 0 else "Snuke")
    else:
        print("Fennec" if odd_count % 2 == 1 else "Snuke")

if __name__ == "__main__":
    main()
